                "মেয়ারের সম্পর্ক:  - C_v = R$, এবং $\\gamma = \\frac{C_p}{C_v}$",
                "সমোষ্ণ কাজে:  = nRT \\ln\\left(\\frac{V_2}{V_1}\\right) = nRT \\ln\\left(\\frac{P_1}{P_2}\\right)$",
                "রুদ্ধতাপীয় সম্পর্ক: ^\\gamma = \\text{ধ্রুবক}$, ^{\\gamma-1} = \\text{ধ্রুবক}$, ^\\gamma P^{1-\\gamma} = \\text{ধ্রুবক}$",
                "কার্নো দক্ষতা: $\\eta = 1 - \\frac{T_2}{T_1} = \\frac{W}{Q_1} = \\frac{Q_1 - Q_2}{Q_1}$",
