        summary: "পদার্থবিজ্ঞানের মূল ভিত্তি হলো পরিমাপ। ভৌত জগতে যা কিছু পরিমাপ করা যায় তাকে রাশি বলে। রাশি প্রধানত দুই প্রকার— মৌলিক রাশি (যেগুলো স্বাধীন, যেমন দৈর্ঘ্য, ভর, সময় ইত্যাদি) এবং লব্ধ রাশি (যা মৌলিক রাশির ওপর নির্ভরশীল, যেমন বেগ, ত্বরণ, বল ইত্যাদি)। পরিমাপের সূক্ষ্মতার জন্য স্লাইড ক্যালিপার্স ও স্ক্রু গজ ব্যবহৃত হয়। যেকোনো পরিমাপে যান্ত্রিক, ব্যক্তিগত বা পরিবেশগত কারণে অনিশ্চয়তা বা ত্রুটি থাকতে পারে।",
