                marks: "১০",
                stimulus: "স্থির অবস্থান থেকে একটি 800 kg ভরের প্রাইভেট কার $2.5\\text{ m/s}^2$ সুষম ত্বরণে চলা শুরু করে 8 সেকেন্ড চলল। এরপর গাড়িটি 15 সেকেন্ড সমবেগে চলল। এরপর চালক ব্রেক চেপে 4 সেকেন্ডে গাড়িটিকে সম্পূর্ণ থামিয়ে দিলেন।",
