            "নিউটনের দ্বিতীয় সূত্র: বস্তুর ভরবেগের পরিবর্তনের হার তার ওপর প্রযুক্ত বলের সমানুপাতিক ($F = ma$)।",
            "ভরবেগের সংরক্ষণশীলতা নীতি: $m_1 u_1 + m_2 u_2 = m_1 v_1 + m_2 v_2$।",
            "নিউটনের তৃতীয় সূত্র: প্রত্যেক ক্রিয়ারই একটি সমান ও বিপরীত প্রতিক্রিয়া আছে ($F_1 = -F_2$)।",
            "ঘর্ষণ ৪ প্রকার: স্থিতি ঘর্ষণ, পিছলানো ঘর্ষণ, আবর্ত ঘর্ষণ ও প্রবাহী ঘর্ষণ।"
