            { q: "সাম্য বল কাকে বলে?", a: "কোনো বস্তুর ওপর একাধিক বল ক্রিয়া করার পর যদি লব্ধি বল শূন্য হয়, তবে সেই বলগুলোকে সাম্য বল বলে।" },
            { q: "নিউটনের ৩য় সূত্রটি লেখো।", a: "প্রত্যেক ক্রিয়ারই একটি সমান ও বিপরীত প্রতিক্রিয়া আছে।" }
