        summary: "বল প্রয়োগের ফলে যদি বস্তুর সরণ ঘটে তবে কাজ সম্পন্ন হয় ($W = Fs$)। বলের দিকে সরণ হলে ধনাত্মক কাজ এবং বলের বিপরীত দিকে সরণ হলে ঋণাত্মক কাজ। কাজ করার সামর্থ্যই হলো শক্তি। যান্ত্রিক শক্তি প্রধানত দুই প্রকার— গতিশক্তি ($E_k = \\frac{1}{2}mv^2$) ও বিভব শক্তি ($E_p = mgh$)। মহাবিশ্বে শক্তির কোনো সৃষ্টি বা ধ্বংস নেই, শক্তি কেবল এক রূপ থেকে অন্য রূপে রূপান্তরিত হতে পারে। কাজ করার হারকে ক্ষমতা ($P = \\frac{W}{t}$) বলে এবং প্রদত্ত শক্তির কত অংশ কার্যকর কাজে রূপ নিল তার অনুপাতই কর্মদক্ষতা।",
