                solution: "পানির ভর $m = 5000\\text{ kg}$, $h = 15\\text{ m}$, সময় $t = 10 \\times 60 = 600\\text{ s}$\nপ্রদত্ত মোট ক্ষমতা $P_{\\text{in}} = 2\\text{ HP} = 2 \\times 746 = 1492\\text{ W}$\nকার্যকর ক্ষমতা $P_{\\text{out}} = \\frac{mgh}{t} = \\frac{5000 \\times 9.8 \\times 15}{600} = \\frac{735000}{600} = 1225\\text{ W}$\nকর্মদক্ষতা $\\eta = \\frac{1225}{1492} \\times 100\\% = 82.10\\%$।"
