            { q: "নদীর পানি অপেক্ষা সমুদ্রের পানিতে সাঁতার কাটা সহজ কেন? [চট্টগ্রাম বোর্ড ২০২৩]", a: "সমুদ্রের পানিতে প্রচুর লবণ দ্রবীভূত থাকায় সমুদ্রের পানির ঘনত্ব নদীর বিশুদ্ধ পানির ঘনত্বের চেয়ে বেশি ($\\rho_{\\text{sea}} > \\rho_{\\text{river}}$)। আমরা জানি প্লবতা $F_B = V\\rho g$, যা তরলের ঘনত্বের সমানুপাতিক। ঘনত্ব বেশি হওয়ায় সমুদ্রের পানি সাঁতারুর ওপর বেশি প্লবতা (উর্ধ্বমুখী বল) প্রয়োগ করে, ফলে সহজেই ভেসে থাকা যায়।" },
            { q: "পেরেকের অগ্রভাগ চোখা রাখা হয় কেন? [কুমিল্লা বোর্ড ২০২৪]", a: "আমরা জানি চাপ $P = \\frac{F}{A}$, অর্থাৎ ক্ষেত্রফল কমলে চাপ বহুগুণ বৃদ্ধি পায়। পেরেকের অগ্রভাগ চোখা হওয়ায় এর স্পর্শ ক্ষেত্রফল অত্যন্ত কম হয়। ফলে হাতুড়ি দিয়ে সামান্য বল প্রয়োগ করলেই পেরেকটির মাথায় প্রচণ্ড চাপের সৃষ্টি হয় এবং তা সহজেই কাঠের বা দেয়ালের ভেতরে প্রবেশ করে।" },
            { q: "বাঁধের তলদেশ ওপরের চেয়ে চওড়া বা প্রশস্ত করা হয় কেন?", a: "তরলের অভ্যন্তরে চাপ গভীরতার সমানুপাতিক ($P = h\\rho g$)। বাঁধের ওপরের চেয়ে তলদেশে পানির গভীরতা সবচেয়ে বেশি থাকে, ফলে তলদেশে পানির চাপও সর্বাধিক হয়। এই প্রচণ্ড পার্শ্বচাপ সহ্য করার জন্য বাঁধের তলদেশকে অনেক চওড়া ও মজবুত করে নির্মাণ করা হয়।" }
