            { q: "পানির ব্যতিক্রান্ত প্রসারণ বলতে কী বোঝায়?", a: "সাধারণত যেকোনো তরলকে তাপ দিলে তার আয়তন বাড়ে। কিন্তু $0^\\circ\\text{C}$ তাপমাত্রার পানিকে তাপ দিলে $4^\\circ\\text{C}$ পর্যন্ত এর আয়তন বাড়ার বদলে হ্রাস পায় এবং ঘনত্ব সর্বাধিক হয়। $4^\\circ\\text{C}$ এর পর পুনরায় আয়তন বাড়তে থাকে। পানির এই অস্বাভাবিক তাপীয় আচরণকে ব্যতিক্রান্ত প্রসারণ বলে।" }
