                question: "$25^\\circ\\text{C}$ তাপমাত্রার 500 g পানিতে $100^\\circ\\text{C}$ তাপমাত্রার 100 g তামার টুকরা ফেললে মিশ্রণের চূড়ান্ত তাপমাত্রা কত হবে? ($s_{\\text{water}}=4200, s_{\\text{copper}}=400$)",
                solution: "ধরি মিশ্রণের তাপমাত্রা = $\\theta$\nতামা কর্তৃক বর্জিত তাপ $Q_1 = m_c s_c (100 - \\theta) = 0.1 \\times 400 \\times (100 - \\theta) = 40(100 - \\theta) = 4000 - 40\\theta$\nপানি কর্তৃক গৃহীত তাপ $Q_2 = m_w s_w (\\theta - 25) = 0.5 \\times 4200 \\times (\\theta - 25) = 2100(\\theta - 25) = 2100\\theta - 52500$\nক্যালরিমিতির নীতি অনুসারে: $Q_1 = Q_2$\n$\\implies 4000 - 40\\theta = 2100\\theta - 52500 \\implies 2140\\theta = 56500$\n$\\implies \\theta = \\frac{56500}{2140} = 26.40^\\circ\\text{C}$।"
