            { tag: "সূত্র ৪", expr: "v_T = v_0 + 0.6\\theta", note: "তাপমাত্রার সাথে শব্দের বেগের পরিবর্তন" },
            { tag: "সূত্র ৫", expr: "T = 2\\pi\\sqrt{\\frac{L}{g}}", note: "সরল দোলকের দোলনকাল সমীকরণ" }
