        summary: "আলো কোনো সমসত্ত্ব স্বচ্ছ মাধ্যমে সরলরেখায় চলে। আলো যখন এক মাধ্যম থেকে অন্য মাধ্যমে আপতিত হয় তখন কিছু আলো প্রথম মাধ্যমে ফিরে আসে, একে প্রতিফলন বলে। সমতল দর্পণে বিম্বের দূরত্ব লক্ষ্যবস্তুর দূরত্বের সমান হয়, বিম্ব অবাস্তব ও সোজা হয় এবং পার্শ্বীয় পরিবর্তন ঘটে। গোলীয় দর্পণ দুই প্রকার— অবতল ও উত্তল। অবতল দর্পণ বাস্তব ও অবাস্তব উভয় বিম্ব তৈরি করতে পারে, কিন্তু উত্তল দর্পণ সর্বদা খর্বিত, অবাস্তব ও সোজা বিম্ব তৈরি করে। গোলীয় দর্পণের সমীকরণ $\\frac{1}{u} + \\frac{1}{v} = \\frac{1}{f}$।",
