            { q: "বাস্তব ও অবাস্তব প্রতিবিম্বের দুটি মৌলিক পার্থক্য লেখো।", a: "১. বাস্তব বিম্ব আলোকরশ্মির প্রকৃত মিলনের ফলে সৃষ্টি হয়, কিন্তু অবাস্তব বিম্ব রশ্মিগুলো কোনো বিন্দু থেকে অপসৃত হচ্ছে বলে মনে হয়। ২. বাস্তব বিম্বকে পর্দায় ফেলা যায় ও উল্টো হয়, কিন্তু অবাস্তব বিম্ব পর্দায় ফেলা যায় না এবং সর্বদা সোজা হয়।" }
