                stimulus: "15 cm ফোকাস দূরত্বের একটি অবতল দর্পণের প্রধান অক্ষের ওপর দর্পণ থেকে 25 cm দূরত্বে 5 cm দৈর্ঘ্যের একটি লক্ষ্যবস্তু রাখা হলো।",
