            { term: "লেন্সের ক্ষমতা (Power of Lens)", desc: "কোনো লেন্সের আলোকরশ্মিগুচ্ছকে অভিসারী বা অপসারী করার সামর্থ্যকে লেন্সের ক্ষমতা বলে। একক ডায়োপ্টার (D)।" },
            { term: "অপটিক্যাল ফাইবার", desc: "কাঁচ বা স্বচ্ছ প্লাস্টিকের তৈরি অতি সূক্ষ্ম নমনীয় তন্তু যার ভেতর দিয়ে পূর্ণ অভ্যন্তরীণ প্রতিফলনের সাহায্যে আলোক সংকেত দ্রুত পরিবাহিত হয়।" }
