            { tag: "সূত্র ২", expr: "\\sin \\theta_c = \\frac{1}{n}", note: "সংকট কোণ ও প্রতিসরাঙ্কের সম্পর্ক" },
            { tag: "সূত্র ৩", expr: "\\frac{1}{u} + \\frac{1}{v} = \\frac{1}{f}", note: "লেন্সের মৌলিক সমীকরণ" },
            { tag: "সূত্র ৪", expr: "P = \\frac{1}{f\\text{ (মিটার)}}", note: "লেন্সের ক্ষমতা (ডায়োপ্টার D)" }
