            { q: "লেন্সের আলোক কেন্দ্র কাকে বলে?", a: "লেন্সের প্রধান অক্ষের ওপর অবস্থিত যে বিন্দুর মধ্য দিয়ে আলোকরশ্মি গমন করলে কোনো দিক পরিবর্তন না করে সোজা বেরিয়ে যায় তাকে আলোক কেন্দ্র বলে।" }
