                ans_b: "স্পর্শ পদ্ধতিতে বস্তুতে স্থায়ী আধান সঞ্চালিত হয় এবং উৎস চার্জ কমে যায়। কিন্তু আবেশ পদ্ধতিতে কোনো স্পর্শ ছাড়াই কেবল উপস্থিতিতে ক্ষণস্থায়ী আধান আবিষ্ট হয় এবং মূল আধান অক্ষত থাকে।",
                q_c: "আধানদ্বয়ের মধ্যবর্তী ক্রিয়াশীল বিকর্ষণ বলের মান নির্ণয় করো।",
                ans_c: "এখানে,\n$q_1 = 25\\text{ C}$, $q_2 = 64\\text{ C}$, $r = 40\\text{ cm} = 0.4\\text{ m}$\n$k = 9 \\times 10^9\\text{ N}\\cdot\\text{m}^2/\\text{C}^2$\nকুলম্বের সূত্রানুযায়ী:\n$F = k \\frac{q_1 q_2}{r^2} = \\frac{(9 \\times 10^9) \\times 25 \\times 64}{(0.4)^2} = \\frac{1.44 \\times 10^{13}}{0.16} = 9 \\times 10^{13}\\text{ N}$।\nউত্তর: বলের মান $9 \\times 10^{13}\\text{ N}$।"
