                stimulus: "একটি বাড়িতে প্রতিদিন 220V এর চারটি 60W এর বাতি 6 ঘণ্টা, তিনটি 80W এর ফ্যান 10 ঘণ্টা এবং একটি 1000W এর হিটার 2 ঘণ্টা করে চালানো হয়। প্রতি ইউনিট বিদ্যুতের মূল্য 7.50 টাকা।",
