        summary: "১৮২০ সালে বিজ্ঞানী ওয়েরস্টেড আবিষ্কার করেন যে পরিবাহীর মধ্য দিয়ে বিদ্যুৎ প্রবাহিত হলে তার চারপাশে একটি চৌম্বক ক্ষেত্র তৈরি হয়। তারের কুন্ডলী বা সোলেনয়েডের মধ্য দিয়ে বিদ্যুৎ পাঠালে তা শক্তিশালী তড়িৎ চুম্বকে পরিণত হয়। তড়িৎ প্রবাহের ওপর চৌম্বক ক্ষেত্রের বলের নীতিতে বৈদ্যুতিক মোটর কাজ করে (তড়িৎ শক্তি যান্ত্রিক শক্তিতে রূপান্তরিত হয়)। বিজ্ঞানী ফ্যারাডে আবিষ্কার করেন যে চৌম্বক ক্ষেত্রের পরিবর্তনের মাধ্যমে কুণ্ডলীতে বিদ্যুৎ আবিষ্ট করা যায়, যা জেনারেটরের মূল ভিত্তি। ট্রান্সফরমারের মাধ্যমে এসি ভোল্টেজকে সুবিধাজনক মানে বাড়ানো বা কমানো যায়।",
