            { term: "ডোপিং (Doping)", desc: "বিশুদ্ধ অর্ধপরিবাহীর তড়িৎ পরিবাহিতা বহুগুণ বৃদ্ধি করার জন্য নিয়ন্ত্রিত উপায়ে নির্দিষ্ট অপদ্রব্য মেশানোর প্রক্রিয়াকে ডোপিং বলে।" },
            { term: "রেকটিফিকেশন (একমুখীকরণ)", desc: "দিক পরিবর্তী প্রবাহকে (AC) একমুখী প্রবাহে (DC) রূপান্তর করার প্রক্রিয়াকে রেকটিফিকেশন বলে।" }
