                ans_d: "তেজস্ক্রিয় ক্ষয় সূত্র $N = N_0 e^{-\\lambda t}$ অনুসারে, পরমাণু ক্ষয়ের হার অবশিষ্ট পরমাণু সংখ্যার সমানুপাতিক ($\\frac{dN}{dt} \\propto -N$)। প্রতিটি অর্ধায়ুতে বর্তমান সংখ্যার ঠিক অর্ধেক ক্ষয় হয়।\n১ম অর্ধায়ুতে: ৫০% অবশিষ্ট থাকে।\n২য় অর্ধায়ুতে: ২৫% অবশিষ্ট থাকে।\n৩য় অর্ধায়ুতে: ১২.৫% অবশিষ্ট থাকে।\nগাণিতিকভাবে $N = 0$ হতে হলে সময় $t \\to \\infty$ হতে হবে। অর্থাৎ অনন্তকাল সময় অতিবাহিত না হলে তাত্ত্বিকভাবে পরমাণু সংখ্যা কখনো পুরোপুরি শূন্য হতে পারে না। সর্বদা কিছু না কিছু পরমাণু বিদ্যমান থাকবে।"
